import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './button.module.scss'

export type ButtonVariant =
  | 'primary'
  | 'secondary'
  | 'outline'
  | 'ghost'
  | 'destructive'
  | 'link'

export type ButtonSize = 'sm' | 'md' | 'lg' | 'icon'

const VARIANT: Record<ButtonVariant, string> = {
  primary: styles.primary,
  secondary: styles.secondary,
  outline: styles.outline,
  ghost: styles.ghost,
  destructive: styles.destructive,
  link: styles.link,
}

const SIZE: Record<ButtonSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
  icon: styles.icon,
}

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant
  size?: ButtonSize
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'primary', size = 'md', type = 'button', ...props }, ref) => (
    <button
      ref={ref}
      type={type}
      className={cx(styles.root, VARIANT[variant], SIZE[size], className)}
      {...props}
    />
  ),
)

Button.displayName = 'Button'

@use 'styles' as vz;

.root {
  --btn-bg: transparent;
  --btn-fg: currentcolor;
  --btn-border: transparent;
  --btn-shadow: none;
  --btn-height: #{vz.space(9)};
  --btn-px: #{vz.space(4)};
  --btn-radius: #{vz.radius('lg')};
  --btn-font-size: #{vz.font-size('sm')};
  --btn-active-scale: 0.98;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: vz.space(2);
  height: var(--btn-height);
  padding: 0 var(--btn-px);
  border: 1px solid var(--btn-border);
  border-radius: var(--btn-radius);
  background: var(--btn-bg);
  color: var(--btn-fg);
  box-shadow: var(--btn-shadow);
  font-size: var(--btn-font-size);
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition:
    background-color vz.duration('base') vz.ease('out'),
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out'),
    color vz.duration('base') vz.ease('out'),
    transform vz.duration('fast') vz.ease('out');

  @include vz.focus-ring(2px, 2px, 0.65);

  @include vz.active {
    transform: scale(var(--btn-active-scale));
  }

  @include vz.disabled {
    opacity: 0.5;
    pointer-events: none;
  }

  @include vz.motion-reduce {
    transition: none;

    @include vz.active {
      transform: none;
    }
  }

  svg {
    @include vz.icon(4);

    pointer-events: none;
  }
}

.primary {
  --btn-bg: #{vz.color('primary')};
  --btn-fg: #{vz.color('primary-foreground')};
  --btn-shadow: #{vz.elevation(1)};

  @include vz.hover {
    --btn-bg: #{vz.color('primary', 0.9)};
  }
}

.secondary {
  --btn-bg: #{vz.color('secondary')};
  --btn-fg: #{vz.color('secondary-foreground')};

  @include vz.hover {
    --btn-bg: #{vz.color('secondary', 0.8)};
  }
}

.outline {
  --btn-bg: #{vz.color('background')};
  --btn-border: #{vz.color('border')};

  @include vz.hover {
    --btn-bg: #{vz.color('accent')};
    --btn-fg: #{vz.color('accent-foreground')};
  }
}

.ghost {
  @include vz.hover {
    --btn-bg: #{vz.color('accent')};
    --btn-fg: #{vz.color('accent-foreground')};
  }
}

.destructive {
  --btn-bg: #{vz.color('destructive')};
  --btn-fg: #{vz.color('destructive-foreground')};
  --btn-shadow: #{vz.elevation(1)};

  @include vz.hover {
    --btn-bg: #{vz.color('destructive', 0.9)};
  }
}

.link {
  --btn-fg: #{vz.color('primary')};
  --btn-active-scale: 1;

  text-underline-offset: 4px;

  @include vz.hover {
    text-decoration: underline;
  }
}

.sm {
  --btn-height: #{vz.space(8)};
  --btn-px: #{vz.space(3)};
  --btn-radius: #{vz.radius('sm')};
  --btn-font-size: #{vz.font-size('xs')};
}

.lg {
  --btn-height: #{vz.space(11)};
  --btn-px: #{vz.space(6)};
  --btn-radius: #{vz.radius('xl')};
}

.icon {
  --btn-px: 0;

  width: var(--btn-height);
}
